      /// <summary>
      /// 图像坐标系下计算角度：
      /// 上=0°，右=90°，下=180°，左=270°，顺时针为正
      /// </summary>
      private float CalcWaferAngle(float cx, float cy, float px, float py)
      {
          float dx = px - cx;
          float dy = py - cy;

          if (Math.Abs(dx) < 1e-9 && Math.Abs(dy) < 1e-9)
              return 0.0F;

          float angle = (float)(Math.Atan2(dx, -dy) * 180.0F / Math.PI);

          angle %= 360.0F;
          if (angle < 0.0)
              angle += 360.0F;

          return angle;
      }



    
