## 模式 9：带状态的多次执行

**场景**：Process() 需要在多次执行间保持状态

```csharp
public partial class UserScript : ScriptMethods, IProcessMethods
{
    int processCount;
    int totalCount;
    float accumulatedValue;
    string errorStatus = string.Empty;

    public void Init()
    {
        processCount = 0;
        totalCount = 0;
        accumulatedValue = 0f;
        errorStatus = string.Empty;
    }

    /// <summary>
    /// 流程执行函数
    /// </summary>
    public bool Process()
    {
        try
        {
            errorStatus = string.Empty;

            processCount++;
            totalCount++;

            // 直接赋值获取输入
            float inputVal = in0;

            // 累积计算
            accumulatedValue += inputVal;

            // 每 N 次输出平均值
            if (totalCount % 10 == 0)
            {
                float avg = accumulatedValue / totalCount;
                out0 = avg;
                countOut = totalCount;
            }

            return true;
        }
        catch (Exception ex)
        {
            errorStatus = "Process 异常：" + ex.Message;
            return false;
        }
    }

    // 本模式无非托管资源，按"仅在需要显式释放资源时才编写 Dispose()"规则省略
}
```

